CREATE OR REPLACE FUNCTION trigger_is_ecommerce_purchase()
RETURNS TRIGGER AS $$
BEGIN
	--- duplicate inheritance
	IF EXISTS (SELECT 1 FROM physical_purchase WHERE physical_purchase.pk_fk_purchase = new.pk_fk_purchase) THEN
		RAISE EXCEPTION 'This purchase is already for a physical location';
	END IF;
	IF TG_OP = 'INSERT' THEN
        UPDATE purchase set is_physical_purchase = false WHERE purchase.pk_id = new.pk_fk_purchase;
		RETURN NEW;
	ELSE
		UPDATE purchase set is_physical_purchase = null WHERE purchase.pk_id = new.pk_fk_purchase;
		RETURN OLD;
    END IF;
	
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER trigger_is_ecommerce_purchase BEFORE INSERT OR DELETE
    ON ecommerce_purchase
	FOR EACH ROW
    EXECUTE FUNCTION trigger_is_ecommerce_purchase ( )
;

