CREATE OR REPLACE FUNCTION trigger_available_ecommerce()
RETURNS TRIGGER AS $$
BEGIN
	IF TG_OP = 'INSERT' THEN
		NEW.ecommerce_available_quantity := NEW.quantity - NEW.display_quantity;
	ELSIF TG_OP = 'UPDATE' THEN
		IF NEW.quantity - OLD.quantity = 0 AND NEW.display_quantity - OLD.display_quantity = 0 THEN
			RETURN NEW;
		END IF;
		NEW.ecommerce_available_quantity 
			:= OLD.ecommerce_available_quantity + (NEW.quantity - OLD.quantity ) - (NEW.display_quantity - OLD.display_quantity);
	END IF;
	
	RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER trigger_available_ecommerce BEFORE INSERT OR UPDATE
    ON inventory
	FOR EACH ROW
    EXECUTE FUNCTION trigger_available_ecommerce ( )
