CREATE OR REPLACE FUNCTION trigger_employee_is_cashier()
RETURNS TRIGGER AS $$
BEGIN
	IF (SELECT employee.role FROM employee WHERE employee.pk_id = NEW.fk_employee) != 'cashier' THEN
		RAISE EXCEPTION 'The employee must be a cashier';
	END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

