CREATE OR REPLACE FUNCTION trigger_update_total_price()
RETURNS TRIGGER AS $$
BEGIN
	IF TG_OP = 'DELETE' OR TG_OP = 'UPDATE' THEN
		UPDATE purchase set total_price = purchase.total_price - OLD.unit_price*OLD.quantity WHERE purchase.pk_id = OLD.pk_fk_purchase;
	END IF;
	IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
		UPDATE purchase set total_price = purchase.total_price + NEW.unit_price*NEW.quantity WHERE purchase.pk_id = NEW.pk_fk_purchase;
    END IF;
	
	IF TG_OP = 'DELETE' THEN
		RETURN OLD;
	ELSE
		RETURN NEW;
	END IF;
	
END;
$$ LANGUAGE plpgsql;

